import numpy as np
import pandas as pd
from datetime import datetime, timedelta

def r_time_clock_at_tz(time, tz=None, units="secs"):
    """
    Reproduces timechange::time_clock_at_tz.
    Calculates the time since the start of the day in the given timezone.
    R returns a 'difftime' object, which should be represented as a timedelta 
    (or numpy timedelta64) in Python.
    """
    # Handle the case where 'time' is a list/dict (representing a list-like object in R)
    if isinstance(time, dict):
        res = time.copy()
        for nm in res:
            val = res[nm]
            if isinstance(val, (pd.Timestamp, np.datetime64, datetime)):
                res[nm] = _clock_at_tz_internal(val, tz)
        return res

    # Convert input to pandas series of timestamps
    if isinstance(time, (list, np.ndarray)):
        ts = pd.to_datetime(time)
    elif isinstance(time, (pd.Timestamp, np.datetime64, datetime)):
        ts = pd.Timestamp(time)
    elif isinstance(time, pd.Series):
        ts = pd.to_datetime(time)
    else:
        ts = pd.to_datetime([time])

    target_tz = tz if tz is not None else 'UTC'

    if isinstance(ts, pd.Timestamp):
        # Scalar case
        loc_ts = ts.tz_localize('UTC').tz_convert(target_tz) if ts.tz is None else ts.tz_convert(target_tz)
        day_start = loc_ts.normalize()
        diff = loc_ts - day_start
        return _scale_timedelta(diff, units)
    else:
        # Vector case
        if ts.dtype == 'datetime64[ns]':
            ts = ts.tz_localize('UTC')

        loc_ts = ts.tz_convert(target_tz)
        day_start = loc_ts.normalize()
        diffs = loc_ts - day_start

        # Return a numpy array of timedeltas
        return np.array([_scale_timedelta(d, units) for d in diffs], dtype='timedelta64[ns]')

def _clock_at_tz_internal(time, tz):
    ts = pd.Timestamp(time)
    target_tz = tz if tz is not None else 'UTC'
    loc_ts = ts.tz_localize('UTC').tz_convert(target_tz) if ts.tz is None else ts.tz_convert(target_tz)
    day_start = loc_ts.normalize()
    return loc_ts - day_start

def _scale_timedelta(td, units):
    """
    R's difftime essentially scales the time difference.
    However, the prompt asks for the 'natural Python object' for difftime.
    If units are provided, the value is numerically scaled, but it's still a duration.
    R's difftime is internally a double. To preserve the requested units scaling 
    while returning a timedelta object:
    """
    total_seconds = td.total_seconds()

    # Scale the seconds based on R's units
    if units == "secs":
        scale = 1.0
    elif units == "hours":
        scale = 1.0 / 3600.0
    elif units == "mins":
        scale = 1.0 / 60.0
    elif units == "days":
        scale = 1.0 / 86400.0
    elif units == "weeks":
        scale = 1.0 / 604800.0
    else:
        scale = 1.0

    # Return as a timedelta based on the scaled seconds
    return timedelta(seconds=total_seconds * scale)
